// 导出页面为PDF格式,宽度大于高度
/**
 * 用于 t-student-attendance 学生端-学生管理-学生考勤-下载记分册（任课老师和班主任）
*/
import html2Canvas from 'html2canvas'
import JsPDF from 'jspdf'
export default{
    printPdfBigWidth
}
/**
 * @param  ele          要生成 pdf 的DOM元素（容器）
 * @param  pdfName     PDF文件生成后的文件名字
 * @param  pos     调整间距 {left:25,top:25}
 * */
function printPdfBigWidth(ele, pdfName) {
  html2Canvas(ele, {
    scale: 2// 提升画面质量，但是会增加文件大小
  }).then(function(canvas) {
    var contentWidth = canvas.width;
    var contentHeight = canvas.height;
    console.log('图片contentWidth:',contentWidth,";图片contentHeight:",contentHeight)
    // 将canvas转为base64图片
    var pageData = canvas.toDataURL("image/jpeg", 1.0);
    var PDF = new JsPDF("p", "pt", "a4");//默认不填时为纵向打印，需横向打印 写 l ,
    PDF.addImage(pageData, "jpeg", 0,0,contentWidth/2*0.75,contentHeight/2*0.75);// 内容区
    let a = pdfName;
    console.log(a);
    let url = PDF.output('datauristring');//在iframe中显示
   // window.open(url);
   // document.getElementById('iframe123').src=url
    sessionStorage.setItem("_imgUrl", url);
    document.getElementById('iframe123').src='./pdfBox/web/viewer.html'
  });
}